"code": "import { COPY } from './copy.js';

const $ = (id) => document.getElementById(id);

function setAttr(el, attr, value) {
  if (el.getAttribute(attr) !== String(value)) {
    el.setAttribute(attr, value);
  }
}

function setBool(el, prop, value) {
  if (el[prop] !== !!value) {
    el[prop] = !!value;
  }
}

function setText(el, text) {
  if (el.textContent !== text) {
    el.textContent = text;
  }
}

export function renderTimer(view) {
  const { readReady, session, error, fieldInvalid, configOpen } = view;
  const isKnown = readReady && session;
  const isRunning = isKnown && session.state === 'running';
  const isPaused = isKnown && session.state === 'paused';
  const isCompleted = isKnown && session.state === 'completed';
  const isUnknown = !readReady || !session;
  const isConfigOpen = !!configOpen;

  // 1. Time Readout
  const timeReadout = $('time-readout');
  const minutesEl = $('minutes');
  const secondsEl = $('seconds');

  if (isKnown) {
    setBool(timeReadout, 'hidden', false);
    const m = String(Math.floor(session.minutes / 60)).padStart(2, '0');
    const s = String(session.minutes % 60).padStart(2, '0');
    setText(minutesEl, m);
    setText(secondsEl, s);
  } else {
    setBool(timeReadout, 'hidden', true);
    setText(minutesEl, '--');
    setText(secondsEl, '--');
  }

  // 2. Completed View
  const completedSection = $('completed');
  const completedTitle = $('completed-title');
  const completedDuration = $('completed-duration');

  if (isCompleted) {
    setBool(completedSection, 'hidden', false);
    setText(completedTitle, COPY.completedTitle);
    setText(completedDuration, `설정한 시간 ${session.durationMinutes}분`);
  } else {
    setBool(completedSection, 'hidden', true);
  }

  // 3. Unknown Time View
  const unknownTime = $('unknown-time');

  if (isUnknown) {
    setBool(unknownTime, 'hidden', false);
  } else {
    setBool(unknownTime, 'hidden', true);
  }

  // 4. Paused Status
  const pausedStatus = $('paused-status');

  if (isPaused) {
    setBool(pausedStatus, 'hidden', false);
  } else {
    setBool(pausedStatus, 'hidden', true);
  }

  // 5. Screen Title
  const screenTitle = $('screen-title');
  if (isCompleted) {
    setBool(screenTitle, 'hidden', true);
  } else {
    setBool(screenTitle, 'hidden', false);
  }

  // 6. Primary Action Button
  const primaryBtn = $('primary-action');
  const primaryIcon = $('primary-icon');
  const primaryLabel = $('primary-label');

  if (isKnown) {
    setBool(primaryBtn, 'disabled', false);
    if (isRunning) {
      setText(primaryLabel, COPY.pause);
      setAttr(primaryIcon, 'src', 'assets/icons/Pause-light.svg');
    } else if (isPaused) {
      setText(primaryLabel, COPY.resume);
      setAttr(primaryIcon, 'src', 'assets/icons/Play-light.svg');
    } else if (isCompleted) {
      setText(primaryLabel, COPY.restart);
      setAttr(primaryIcon, 'src', 'assets/icons/Play-light.svg');
    }
  } else {
    setBool(primaryBtn, 'disabled', true);
    setText(primaryLabel, COPY.start);
    setAttr(primaryIcon, 'src', 'assets/icons/Play-light.svg');
  }

  // 7. Reset Button
  const resetBtn = $('reset-session');
  if (isRunning || isPaused) {
    setBool(resetBtn, 'hidden', false);
  } else {
    setBool(resetBtn, 'hidden', true);
  }

  // 8. Configure Button
  const configureBtn = $('configure-duration');
  if (isCompleted) {
    setBool(configureBtn, 'disabled', false);
    setBool(configureBtn, 'hidden', false);
  } else if (isKnown) {
    setBool(configureBtn, 'hidden', true);
  } else {
    setBool(configureBtn, 'disabled', true);
    setBool(configureBtn, 'hidden', false);
  }

  // 9. Error Regions
  const mainErrorRegion = $('main-error-region');
  const mainError = $('main-error');
  const configErrorRegion = $('config-error-region');
  const configError = $('config-error');

  let errorText = null;
  if (error) {
    switch (error) {
      case 'READ_FAILED': errorText = COPY.readError; break;
      case 'WRITE_FAILED': errorText = COPY.writeError; break;
      case 'INVALID_CLOCK': errorText = COPY.clockError; break;
      default: errorText = COPY.transitionError;
    }
  }

  // Determine where to show the error
  // If config is open, show config error region
  // If config is closed, show main error region
  // Priority: unavailableConfig (if config open and known) > store error

  if (isConfigOpen) {
    // Config Error Region
    let configErrMsg = null;
    if (isKnown && (isRunning || isPaused)) {
      configErrMsg = COPY.unavailableConfig;
    } else if (error) {
      configErrMsg = errorText;
    }

    if (configErrMsg) {
      setBool(configErrorRegion, 'hidden', false);
      setText(configError, configErrMsg);
    } else {
      setBool(configErrorRegion, 'hidden', true);
    }

    // Main Error Region should be hidden if config is open
    setBool(mainErrorRegion, 'hidden', true);
  } else {
    // Config Error Region hidden
    setBool(configErrorRegion, 'hidden', true);

    // Main Error Region
    if (errorText) {
      setBool(mainErrorRegion, 'hidden', false);
      setText(mainError, errorText);
    } else {
      setBool(mainErrorRegion, 'hidden', true);
    }
  }

  // 10. Duration Input Validation
  const durationInput = $('duration-input');
  const durationError = $('duration-error');
  const applyBtn = $('apply-duration');

  if (fieldInvalid) {
    setText(durationError, COPY.invalidDuration);
    setAttr(durationInput, 'aria-invalid', 'true');
  } else {
    setText(durationError, '');
    setAttr(durationInput, 'aria-invalid', 'false');
  }

  // 11. Apply Button Enabled State
  // Enabled only when known (ready or completed)
  // Note: The prompt says "Apply enabled only known ready/completed"
  // It doesn't explicitly say disabled when unknown, but usually apply is tied to the form validity.
  // However, the prompt says "disable primary/configure/apply" for unknown.
  // Let's check the prompt again: "disable primary/configure/apply" for unknown.
  if (isUnknown) {
    setBool(applyBtn, 'disabled', true);
  } else if (isKnown) {
    setBool(applyBtn, 'disabled', false);
  }
}"
}
